private static void particleCloud(LivingEntity entity) {
        Vec3 pos = entity.position().add(0, entity.getBbHeight() / 2, 0);
        MagicManager.spawnParticles(entity.level, ParticleTypes.PORTAL, pos.x, pos.y, pos.z, 70, entity.getBbWidth() / 4, entity.getBbHeight() / 5, entity.getBbWidth() / 4, .035, false);
    }

@SubscribeEvent
    public static void onLivingIncomingDamage(LivingIncomingDamageEvent event) {
        var livingEntity = event.getEntity();
        //irons_spellbooks.LOGGER.debug("onLivingAttack.1: {}", livingEntity);
        if (event.getSource().getEntity() != null && livingEntity.getVehicle() instanceof IceTombEntity iceTomb && !DamageSources.isFriendlyFireBetween(event.getSource().getEntity(), livingEntity)) {
            // redirect entity-caused damage away from entombed players into the tomb
            event.setCanceled(true);
            iceTomb.hurt(event.getSource(), event.getOriginalAmount());
            return;
        }
        if ((livingEntity instanceof ServerPlayer) || (livingEntity instanceof IMagicEntity)) {
            if (ItemRegistry.FIREWARD_RING.get().isEquippedBy(livingEntity) && event.getSource().is(DamageTypeTags.IS_FIRE)) {
                event.getEntity().clearFire();
                event.setCanceled(true);
                return;
            }
            var playerMagicData = MagicData.getPlayerMagicData(livingEntity);
            if (livingEntity.hasEffect(MobEffectRegistry.EVASION)) {
                if (EvasionEffect.doEffect(livingEntity, event.getSource())) {
                    event.setCanceled(true);
                    return;
                }
            } else if (livingEntity.hasEffect(MobEffectRegistry.ABYSSAL_SHROUD)) {
                if (AbyssalShroudEffect.doEffect(livingEntity, event.getSource())) {
                    event.setCanceled(true);
                    return;
                }
            }

            if (livingEntity instanceof ServerPlayer serverPlayer) {
                if (playerMagicData.isCasting() &&
                        playerMagicData.getCastingSpell().getSpell().canBeInterrupted(serverPlayer) &&
                        playerMagicData.getCastDurationRemaining() > 0 &&
                        !event.getSource().is(DamageTypeTagGenerator.LONG_CAST_IGNORE) &&
                        !playerMagicData.popMarkedPoison()) {
                    Utils.serverSideCancelCast(serverPlayer);
                }
            }
        }
        if (ServerConfigs.BETTER_CREEPER_THUNDERHIT.get() && event.getSource().is(DamageTypeTags.IS_FIRE) && event.getEntity() instanceof Creeper creeper && creeper.isPowered()) {
            event.setCanceled(true);
            return;
        }
    }

public static boolean handleSpellTeleport(AbstractSpell spell, Entity entity, Vec3 destination) {
        var event = new SpellTeleportEvent(spell, entity, destination.x, destination.y, destination.z);
        NeoForge.EVENT_BUS.post(event);
        boolean canceled = event.isCanceled();
        if (!canceled) {
            entity.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
        }
        return canceled;
    }

@Override
    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        Vec3 dest = null;
        var teleportData = (TeleportSpell.TeleportData) playerMagicData.getAdditionalCastData();
        if (teleportData != null) {
            var potentialTarget = teleportData.getTeleportTargetPosition();
            if (potentialTarget != null) {
                dest = potentialTarget;
                Utils.handleSpellTeleport(this, entity, dest);
            }
        } else {
            HitResult hitResult = RaycastBuilder.begin(level, entity)
                    .range(getDistance(spellLevel, entity))
                    .checkForBlocks(true)
                    .build();
            if (entity.isPassenger()) {
                entity.stopRiding();
            }
            if (hitResult.getType() == HitResult.Type.ENTITY && ((EntityHitResult) hitResult).getEntity() instanceof LivingEntity target) {
                //dest = target.position().subtract(new Vec3(0, 0, 1.5).yRot(target.getYRot()));
                for (int i = 0; i < 8; i++) {
                    dest = target.position().subtract(new Vec3(0, 0, 1.5).yRot(-(target.getYRot() + i * 45) * Mth.DEG_TO_RAD));
                    if (level.getBlockState(BlockPos.containing(dest).above()).isAir())
                        break;

                }
                Utils.handleSpellTeleport(this, entity, dest.add(0, 1, 0));
                entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition().subtract(0, .15, 0));
            } else {
                dest = TeleportSpell.findTeleportLocation(level, entity, getDistance(spellLevel, entity));
                Utils.handleSpellTeleport(this, entity, dest);

            }
        }
        entity.resetFallDistance();
        level.playSound(null, dest.x, dest.y, dest.z, getCastFinishSound().get(), SoundSource.NEUTRAL, 1f, 1f);

        //Invis take 1 tick to set in
        entity.setInvisible(true);
        entity.addEffect(new MobEffectInstance(MobEffectRegistry.TRUE_INVISIBILITY, 100, 0, false, false, true));


        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

public static boolean handleSpellTeleport(AbstractSpell spell, Entity entity, Vec3 destination) {
        var event = new SpellTeleportEvent(spell, entity, destination.x, destination.y, destination.z);
        NeoForge.EVENT_BUS.post(event);
        boolean canceled = event.isCanceled();
        if (!canceled) {
            entity.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
        }
        return canceled;
    }

@Override
    public void onEffectAdded(LivingEntity livingEntity, int pAmplifier) {
        super.onEffectAdded(livingEntity, pAmplifier);

        var targetingCondition = TargetingConditions.forCombat().ignoreLineOfSight().selector(e -> {
            //IronsSpellbooks.LOGGER.debug("InvisibilitySpell TargetingConditions:{}", e);
            return (((Mob) e).getTarget() == livingEntity);
        });

        //remove aggro from anything targeting us
        livingEntity.level.getNearbyEntities(Mob.class, targetingCondition, livingEntity, livingEntity.getBoundingBox().inflate(40D))
                .forEach(entityTargetingCaster -> {
                    //IronsSpellbooks.LOGGER.debug("InvisibilitySpell Clear Target From:{}", entityTargetingCaster);
                    entityTargetingCaster.setTarget(null);
                    entityTargetingCaster.targetSelector.getAvailableGoals().forEach(WrappedGoal::stop);
                    entityTargetingCaster.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
                });
    }

@SubscribeEvent
    public static void onDealDamage(LivingIncomingDamageEvent event) {
        if (event.getSource().getEntity() instanceof LivingEntity livingAttacker && livingAttacker.hasEffect(MobEffectRegistry.TRUE_INVISIBILITY)) {
            livingAttacker.removeEffect(MobEffectRegistry.TRUE_INVISIBILITY);
        }
    }

@Inject(method = "updateInvisibilityStatus", at = @At(value = "TAIL"))
    public void irons_spellbooks$updateInvisibilityStatus(CallbackInfo ci) {
        LivingEntity self = (LivingEntity) (Object) this;
        if (self.hasEffect(MobEffectRegistry.TRUE_INVISIBILITY))
            self.setInvisible(true);
    }

@Inject(method = "onEffectRemoved", at = @At(value = "HEAD"))
    public void irons_spellbooks$onEffectRemoved(MobEffectInstance effectInstance, CallbackInfo ci) {
        LivingEntity self = (LivingEntity) (Object) this;
        if (!self.level.isClientSide) {
            if (effectInstance.getEffect().value() instanceof IMobEffectEndCallback mobEffect) {
                mobEffect.onEffectRemoved(self, effectInstance.getAmplifier());
            }
            if (effectInstance.getEffect().value() instanceof ISyncedMobEffect && self.level.getChunkSource() instanceof ServerChunkCache serverChunk) {
                serverChunk.broadcast(self, new ClientboundRemoveMobEffectPacket(self.getId(), effectInstance.getEffect()));
            }
        }
    }

@SubscribeEvent
    public static void createEcho(LivingDamageEvent.Post event) {
        var damageSource = event.getSource();
        if (damageSource.getEntity() instanceof LivingEntity attacker && (damageSource.getDirectEntity() == attacker || damageSource.getDirectEntity() instanceof AbstractArrow) && !(damageSource instanceof SpellDamageSource)) {
            var effect = attacker.getEffect(MobEffectRegistry.ECHOING_STRIKES);
            if (effect == null) {
                return;
            }
            var data = EchoingStrikesData.get(attacker);
            if (!data.hasHitsRemaining()) {
                attacker.removeEffect(MobEffectRegistry.ECHOING_STRIKES);
                return;
            }
            var level = attacker.level();
            var percent = getDamageModifier(effect.getAmplifier(), attacker);
            var target = event.getEntity();
            if (damageSource.isDirect()) {
                createEchoingSword(attacker, level, target, event.getNewDamage() * percent);
            } else {
                createEchoingArrow(attacker, level, target, event.getNewDamage() * percent);
            }

            data.decrementHit();
            if (!data.hasHitsRemaining()) {
                attacker.removeEffect(MobEffectRegistry.ECHOING_STRIKES);
            }
        }
    }

private static void createEchoingSword(LivingEntity attacker, Level level, LivingEntity target, float damage) {
        EchoingSword echo = new EchoingSword(EntityRegistry.ECHOING_SWORD.get(), level);
        // todo: real spawn logic
        echo.moveTo(target.getBoundingBox().getCenter().add(new Vec3(2.5, 0, 0).yRot(level.getRandom().nextFloat() * Mth.TWO_PI)).add(Utils.getRandomVec3(1.75)));
        echo.setHomingTarget(target);
        echo.moveAndRotateTowards(target.getBoundingBox().getCenter());
        echo.setExplosionRadius(EchoingStrikesSpell.radius);
        echo.setDamage(damage);
        echo.setOwner(attacker);
        attacker.level.addFreshEntity(echo);
    }

private static void createEchoingArrow(LivingEntity attacker, Level level, LivingEntity target, float damage) {
        EchoingArrowProjectile arrow = new EchoingArrowProjectile(EntityRegistry.ECHOING_ARROW.get(), level);
        Vec3 targetPos = target.getBoundingBox().getCenter();
        Vec3 arrowPos = attacker.position().lerp(targetPos, 0.35);
        Vec3 right = targetPos.subtract(arrowPos).normalize().cross(new Vec3(0, 1, 0));
        Vec3 spawnPos = arrowPos
                .add(right.scale((1 + level.getRandom().nextFloat() * 4) * (level.getRandom().nextBoolean() ? 1 : -1)))
                .add(0, (level.getRandom().nextFloat() - 0.25) * 6, 0);
        arrow.moveTo(spawnPos);
        arrow.setHomingTarget(target);
        arrow.setDamage(damage);
        arrow.setOwner(attacker);
        attacker.level.addFreshEntity(arrow);
    }

